import { renderToStaticMarkup } from "react-dom/server";
import RootLayout, { metadata } from "./layout";
import { COPY } from "@/lib/messages";

jest.mock("next/navigation", () => ({ usePathname: () => "/" }));

describe("RootLayout", () => {
  const html = renderToStaticMarkup(
    // LayoutProps is generated by Next; the layout only reads children.
    <RootLayout {...({ children: <p>page body</p> } as React.ComponentProps<typeof RootLayout>)} />,
  );

  it("declares the language and renders the page inside the shell", () => {
    expect(html).toContain('<html lang="en"');
    expect(html).toContain("page body");
  });

  it("puts a skip link and the site header before the page content", () => {
    const skip = html.indexOf(COPY.skipToContent);
    const header = html.indexOf("<header");
    const body = html.indexOf("page body");
    expect(skip).toBeGreaterThan(-1);
    expect(skip).toBeLessThan(header);
    expect(header).toBeLessThan(body);
  });

  it("sets the title and description from the shared copy", () => {
    expect(metadata.title).toBe(COPY.appName);
    expect(metadata.description).toBe(COPY.appDescription);
  });
});
